def tr(x): 
  s = ''
  while x > 0:
    s = str(x % 3) + s
    x //= 3
  return s

for n in range(1, 100):
  s = tr(n)
  if n % 2 == 0:
    s = '2' + s + tr(2*(n % 3))
  else: 
    s = tr(2*int(s[0])) + s + '2'
  r = int(s, 3)
  if r > 100:
    print(r)
# выбираем минимальное выведенное число
